-- Q:churn_now
WITH u AS (SELECT id, IFNULL(sid_code,'') IN (SELECT sid_code FROM (SELECT sid_code, DATE(created_at) d, SUM(amount) aum FROM `sayakaya.mi_fee_logs.portfolio_with_code` WHERE DATE(created_at)>='2026-01-14' GROUP BY 1,2) GROUP BY sid_code HAVING MAX(aum)>=500000000) hnwi, (referrer_code IS NULL OR UPPER(TRIM(referrer_code)) NOT IN ('RAIZ','RAIZKAYA')) not_raiz FROM `sayakaya.main.users`),
a AS (SELECT t.user_id, MAX(DATE(t.created_at,'Asia/Jakarta')) last_d, MIN(DATE(t.created_at,'Asia/Jakarta')) first_d, COUNT(DISTINCT DATE(t.created_at,'Asia/Jakarta')) days FROM `sayakaya.main.transactions` t JOIN u ON u.id=t.user_id
  WHERE u.not_raiz AND NOT u.hnwi AND t.type='buy' AND t.status IN ('completed','completed_payment','verified','verified_by_operational') AND IFNULL(t.payment_method,'') NOT IN ('manual_bonus','bonus') GROUP BY 1)
SELECT COUNT(*) investors, COUNTIF(days=1) one_buy_day, COUNTIF(DATE_DIFF(CURRENT_DATE('Asia/Jakarta'),last_d,DAY)>90) silent_gt90, COUNTIF(DATE_DIFF(CURRENT_DATE('Asia/Jakarta'),last_d,DAY)>180) silent_gt180, COUNTIF(DATE_DIFF(CURRENT_DATE('Asia/Jakarta'),last_d,DAY)<=90) active_le90 FROM a
-- Q:ga_exclusion
WITH u AS (SELECT id, IFNULL(sid_code,'') IN (SELECT sid_code FROM (SELECT sid_code, DATE(created_at) d, SUM(amount) aum FROM `sayakaya.mi_fee_logs.portfolio_with_code` WHERE DATE(created_at)>='2026-01-14' GROUP BY 1,2) GROUP BY sid_code HAVING MAX(aum)>=500000000) hnwi, (referrer_code IS NULL OR UPPER(TRIM(referrer_code)) NOT IN ('RAIZ','RAIZKAYA')) not_raiz FROM `sayakaya.main.users`), g AS (SELECT DISTINCT user_id FROM `sayakaya.analytics_266759216.events_*` WHERE _TABLE_SUFFIX>='20261001' AND _TABLE_SUFFIX<='20261108' AND event_date>='20261001' AND event_date<='20261108' AND user_id IS NOT NULL)
SELECT COUNT(*) ga_users, COUNTIF(u.id IS NULL) not_in_db, COUNTIF(u.id IS NOT NULL AND NOT u.not_raiz) raiz, COUNTIF(u.hnwi) hnwi, COUNTIF(u.not_raiz AND NOT u.hnwi) kept FROM g LEFT JOIN u ON u.id=g.user_id
-- Q:ga_first_open_and_null_uid
SELECT COUNT(DISTINCT user_pseudo_id) devices, COUNT(DISTINCT IF(user_id IS NULL,user_pseudo_id,NULL)) devices_never_uid_rows FROM `sayakaya.analytics_266759216.events_*` WHERE _TABLE_SUFFIX>='20261001' AND _TABLE_SUFFIX<='20261108' AND event_date>='20261001' AND event_date<='20261108'
-- Q:ga_platform
SELECT platform, COUNT(*) n, COUNT(DISTINCT user_pseudo_id) devices FROM `sayakaya.analytics_266759216.events_*` WHERE _TABLE_SUFFIX>='20261101' AND event_date>='20261101' GROUP BY 1
-- Q:db_vs_ga_stage_octnov
SELECT 'db_registered_cohortB' k, COUNT(*) n FROM `sayakaya.main.users` WHERE DATE(DATETIME_ADD(created_at,INTERVAL 7 HOUR)) BETWEEN '2026-10-01' AND '2026-11-08' AND (referrer_code IS NULL OR UPPER(TRIM(referrer_code)) NOT IN ('RAIZ','RAIZKAYA'))
UNION ALL SELECT 'ga_register_success_users', COUNT(DISTINCT user_id) FROM `sayakaya.analytics_266759216.events_*` WHERE _TABLE_SUFFIX>='20261001' AND _TABLE_SUFFIX<='20261108' AND event_date BETWEEN '20261001' AND '20261108' AND event_name='register_success'
UNION ALL SELECT 'db_verified_cohortB', COUNT(*) FROM `sayakaya.main.users` WHERE verification_status='verified' AND DATE(DATETIME_ADD(verified_at,INTERVAL 7 HOUR)) BETWEEN '2026-10-01' AND '2026-11-08' AND (referrer_code IS NULL OR UPPER(TRIM(referrer_code)) NOT IN ('RAIZ','RAIZKAYA'))
UNION ALL SELECT 'ga_kyc_success_users', COUNT(DISTINCT user_id) FROM `sayakaya.analytics_266759216.events_*` WHERE _TABLE_SUFFIX>='20261001' AND _TABLE_SUFFIX<='20261108' AND event_date BETWEEN '20261001' AND '20261108' AND event_name='kyc_success'
